  "modal.edit.placeholder": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043F\u0435\u0440\u0435\u0432\u043E\u0434 \u0437\u0434\u0435\u0441\u044C...",
  "modal.edit.saveFailed": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F.",
  "modal.edit.fileNotFound": "\u041E\u0448\u0438\u0431\u043A\u0430: \u0444\u0430\u0439\u043B \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0430 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D \u0438\u043B\u0438 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D.",
  "modal.edit.noOverlays": "\u041E\u0448\u0438\u0431\u043A\u0430: \u043D\u0430 \u044D\u0442\u043E\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435 \u043D\u0435\u0442 \u043E\u0432\u0435\u0440\u043B\u0435\u0435\u0432.",
  "modal.edit.blockNotFound": "\u041E\u0448\u0438\u0431\u043A\u0430: \u0438\u0441\u0445\u043E\u0434\u043D\u044B\u0439 \u0431\u043B\u043E\u043A \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0430 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D (\u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E, \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u0431\u044B\u043B\u0430 \u043F\u0435\u0440\u0435\u0432\u0435\u0434\u0435\u043D\u0430 \u0437\u0430\u043D\u043E\u0432\u043E).",
  "modal.edit.updated": "\u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D.",
  // Phase 5 (P0-3): save-on-close confirm dialog strings.
  "modal.edit.unsavedTitle": "\u041D\u0435\u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F",
  "modal.edit.unsavedMessage": "\u0423 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043D\u0435\u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u043A\u0438. \u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043F\u0435\u0440\u0435\u0434 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0435\u043C?",
  "modal.edit.discard": "\u041E\u0442\u043A\u043B\u043E\u043D\u0438\u0442\u044C",
  // ─── Retranslate modal (Phase 17, F-D4-1) ───
  "modal.retranslate.title": "\u041F\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0437\u0430\u043D\u043E\u0432\u043E \u043F\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u043C overlay-\u0431\u043E\u043A\u0441\u0430\u043C",
  "modal.retranslate.scope": "\u041E\u0431\u043B\u0430\u0441\u0442\u044C",
  "modal.retranslate.scope.desc": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435, \u043A\u0430\u043A\u0438\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043F\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0437\u0430\u043D\u043E\u0432\u043E",
  "modal.retranslate.scope.current": "\u0422\u043E\u043B\u044C\u043A\u043E \u0442\u0435\u043A\u0443\u0449\u0430\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430",
  "modal.retranslate.scope.range": "\u0414\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u2026",
  "modal.retranslate.pageRange": "\u0414\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0441\u0442\u0440\u0430\u043D\u0438\u0446",
  "modal.retranslate.pageRange.desc": "\u0412\u043A\u043B\u044E\u0447\u0430\u044E\u0449\u0438\u0439 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0441\u0442\u0440\u0430\u043D\u0438\u0446 (\u0438\u043D\u0434\u0435\u043A\u0441\u044B \u0441 1)",
  "modal.retranslate.from": "\u0421",
  "modal.retranslate.to": "\u041F\u043E",
  "modal.retranslate.onlyEmpty": "\u041F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442\u044C \u0437\u0430\u043D\u043E\u0432\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0443\u0441\u0442\u044B\u0435 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B",
  "modal.retranslate.onlyEmpty.desc": "\u0415\u0441\u043B\u0438 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E, \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442\u044C\u0441\u044F \u0431\u0443\u0434\u0443\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B \u0431\u0435\u0437 \u043F\u0435\u0440\u0435\u0432\u0435\u0434\u0451\u043D\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430.",
  "modal.retranslate.confirmOverwrite": "\u0421\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0442\u044C \u043F\u0435\u0440\u0435\u0434 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0438\u0441\u044C\u044E \u043D\u0435\u043F\u0443\u0441\u0442\u044B\u0445 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u043E\u0432",
  "modal.retranslate.confirmOverwrite.desc": "\u0415\u0441\u043B\u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043E, \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u044B \u0431\u0443\u0434\u0443\u0442 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0438\u0441\u0430\u043D\u044B \u0431\u0435\u0437 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F.",
  "modal.retranslate.noActivePage": "\u0410\u043A\u0442\u0438\u0432\u043D\u0430\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u043D\u0435 \u043E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D\u0430.",
  "modal.retranslate.noFile": "\u0424\u0430\u0439\u043B \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0430 \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E PDF \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D.",
  "modal.retranslate.noOverlays": "\u0421\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u043E\u0432\u0435\u0440\u043B\u0435\u0438 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u044B.",
  "modal.retranslate.invalidRange": "\u041D\u0435\u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0439 \u0438\u043B\u0438 \u043F\u0443\u0441\u0442\u043E\u0439 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0441\u0442\u0440\u0430\u043D\u0438\u0446.",
  "modal.retranslate.noMatching": "\u041D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E overlay-\u044D\u043B\u0435\u043C\u0435\u043D\u0442\u043E\u0432 \u0434\u043B\u044F \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043E\u0431\u043B\u0430\u0441\u0442\u0438.",
